=== JusPrin nozzle change on a named printer ===
wxString change_named_printer_nozzle(Plater& plater, const std::string& name, const std::string& system_preset)
{
    PresetCollection& printers = bundle().printers;
    Preset*           saved    = saved_preset(name);
    if (saved == nullptr || !is_named_printer(*saved))
        return gone();

    const Preset* old_parent = printers.get_preset_parent(*saved);
    // Not const: Preset::save takes its parent's config by pointer.
    Preset*       new_parent = printers.find_preset(system_preset, false, true);
    if (old_parent == nullptr || new_parent == nullptr || !new_parent->is_system)
        return _L("This printer does not come with that nozzle size.");
    if (old_parent == new_parent)
        return {};

    // The open project keeps the printer it has selected, and nothing asks
    // the person anything: Orca's save and its unsaved-changes prompt both go
    // through the selection, so the profile is written here directly. When
    // the project uses this printer its copy follows the saved profile,
    // which would throw away edits nobody has saved yet; those are the
    // person's to settle first.
    const bool in_use = is_selected(name);
    if (in_use && printers.current_is_dirty())
        return _L("The open project has unsaved changes to this printer. Save or discard them in Printer settings, then try "
                  "again.");

    // The new nozzle's profile, plus every setting the person changed on this
    // printer -- except the ones the two nozzle profiles themselves disagree
    // on, which belong to the nozzle.
    DynamicPrintConfig          config  = new_parent->config;
    const auto                  changed = PresetCollection::dirty_options(saved, old_parent);
    const auto                  nozzle  = PresetCollection::dirty_options(new_parent, old_parent);
    const std::set<std::string> nozzle_keys(nozzle.begin(), nozzle.end());
    for (const std::string& key : changed)
        if (nozzle_keys.count(key) == 0)
            config.set_key_value(key, saved->config.option(key)->clone());
    Preset::inherits(config)                                         = new_parent->name;
    config.option<ConfigOptionString>("printer_settings_id", true)->value = name;
    Preset::normalize_inherits(config, new_parent);

    // What PresetCollection::save_current_preset and Tab::save_preset do for
    // the selected profile: store the difference from the parent, and queue
    // the update for the cloud.
    saved->config  = std::move(config);
    saved->base_id = new_parent->setting_id;
    saved->save(&new_parent->config);
    saved->sync_info = "update";
    saved->save_info();

    if (in_use) {
        // The same printer, under the same name: only its settings moved.
        printers.get_edited_preset().config = saved->config;
        plater.update_objects_position_when_select_preset([&] { plater.on_config_change(bundle().full_config()); });
        printer_tab().reload_config();
        printer_tab().update_tab_ui();
    }
    return {};
}

#pragma once

// What the right half of the printer/filament chip says about the project's
// filament slots: one dot per slot, then a label.
//
// Kept apart from the widget so the rules -- which dots are full, which fade,
// when unused slots fold into "+n", when the label names a filament and when
// it counts them -- are plain data that tests can read without wx or Orca.

#include <cstddef>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// One project slot, as the chip needs it.
struct ChipSlot
{
    std::string preset; // the filament preset; slots sharing one print the same filament
    std::string name;   // its short name
    std::string colour; // "#RRGGBB", or empty
    bool        used{false};
};

struct ChipDot
{
    std::size_t slot{0}; // 0-based
    std::string colour;
    bool        faded{false};
};

struct FilamentChipModel
{
    // In slot order.
    std::vector<ChipDot> dots;
    // Unused slots folded into a grey "+n" after the dots; zero draws nothing.
    std::size_t folded{0};
    // More slots in use than fit at full size: every one keeps its dot, and
    // the dots shrink.
    bool shrunk{false};
    // The short name when the slots in use share one filament; empty when the
    // label is a count instead.
    std::string name;
    // How many different filaments the slots in use print with.
    std::size_t filaments{0};
};

// Up to this many dots draw at full size.
constexpr std::size_t kFullSizeDots = 8;

// A plate with nothing on it uses no slot, and a chip of faded dots over a
// count would say nothing about the project. Every slot then reads as in use.
FilamentChipModel describe_filament_chip(const std::vector<ChipSlot>& slots);

} // namespace Slic3r::GUI::JusPrin
=========== cpp
#include "FilamentChipModel.hpp"

#include <algorithm>
#include <set>

namespace Slic3r::GUI::JusPrin {

FilamentChipModel describe_filament_chip(const std::vector<ChipSlot>& slots)
{
    FilamentChipModel model;
    const bool nothing_used = std::none_of(slots.begin(), slots.end(), [](const ChipSlot& slot) { return slot.used; });
    const auto in_use       = [&](const ChipSlot& slot) { return nothing_used || slot.used; };

    std::set<std::string> filaments;
    std::size_t           used = 0;
    for (const ChipSlot& slot : slots)
        if (in_use(slot)) {
            filaments.insert(slot.preset);
            ++used;
        }
    model.filaments = filaments.size();
    if (model.filaments == 1)
        for (const ChipSlot& slot : slots)
            if (in_use(slot)) {
                model.name = slot.name;
                break;
            }

    // Past the full-size count, unused slots give up their dots first; the
    // slots the plate prints with always keep theirs.
    const bool fold = slots.size() > kFullSizeDots;
    for (std::size_t index = 0; index < slots.size(); ++index) {
        const bool active = in_use(slots[index]);
        if (fold && !active) {
            ++model.folded;
            continue;
        }
        model.dots.push_back({index, slots[index].colour, !active});
    }
    model.shrunk = used > kFullSizeDots;
    return model;
}

} // namespace Slic3r::GUI::JusPrin
